package local.tv.quranidle;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import android.view.*;
public class MainActivity extends Activity {
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(70,50,70,30);box.setGravity(Gravity.CENTER);TextView t=new TextView(this);t.setText("تلاوة عند الخمول\nسورة البقرة — ماهر المعيقلي\nتبدأ مع شاشة التوقف، وتتوقف عند استخدامها\nمستوى الصوت أثناء التلاوة لا يزيد على ٧\nالأذان تلقائيًا بصوت ٧\nتنبيه الصلاة: بعد الأذان بـ٧ دقائق لمدة ٢٠ دقيقة");t.setTextSize(25);t.setGravity(Gravity.CENTER);box.addView(t);
 Button on=new Button(this);on.setText("تفعيل");box.addView(on);on.setOnClickListener(v->{getSharedPreferences("state",0).edit().putBoolean("enabled",true).apply();startForegroundService(new Intent(this,IdleService.class));Toast.makeText(this,"تم التفعيل",0).show();});
 Button off=new Button(this);off.setText("إيقاف");box.addView(off);off.setOnClickListener(v->{getSharedPreferences("state",0).edit().putBoolean("enabled",false).apply();stopService(new Intent(this,IdleService.class));Toast.makeText(this,"تم الإيقاف",0).show();});
 setContentView(box);if(getIntent().getBooleanExtra("enable",false)){getSharedPreferences("state",0).edit().putBoolean("enabled",true).apply();startForegroundService(new Intent(this,IdleService.class).setAction(getIntent().getBooleanExtra("adhan_test",false)?"adhan-test":getIntent().getBooleanExtra("prayer_test",false)?"prayer-test":(getIntent().getBooleanExtra("test",false)?"test":"enable")));} }
}
